namespace sv_ee3df36f89604dc1bc9e53bcc8c0e60f.Services;

public class ServerShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-1001"] = new Shipment
        {
            TrackingNumber = "TRK-1001",
            Status = "In Transit",
            Location = "Chicago, IL",
            EstimatedDelivery = new DateTime(2026, 6, 7, 17, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 1, 8, 0, 0, DateTimeKind.Utc), Description = "Package picked up", Location = "New York, NY" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 2, 14, 30, 0, DateTimeKind.Utc), Description = "Arrived at sorting facility", Location = "Philadelphia, PA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 3, 6, 15, 0, DateTimeKind.Utc), Description = "In transit to next facility", Location = "Chicago, IL" },
            ]
        },
        ["TRK-1002"] = new Shipment
        {
            TrackingNumber = "TRK-1002",
            Status = "Delivered",
            Location = "San Francisco, CA",
            EstimatedDelivery = new DateTime(2026, 6, 2, 12, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 5, 28, 9, 0, 0, DateTimeKind.Utc), Description = "Package picked up", Location = "Seattle, WA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 5, 30, 11, 0, 0, DateTimeKind.Utc), Description = "Arrived at local facility", Location = "San Francisco, CA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 1, 10, 45, 0, DateTimeKind.Utc), Description = "Out for delivery", Location = "San Francisco, CA" },
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 1, 14, 20, 0, DateTimeKind.Utc), Description = "Delivered", Location = "San Francisco, CA" },
            ]
        },
        ["TRK-1003"] = new Shipment
        {
            TrackingNumber = "TRK-1003",
            Status = "Processing",
            Location = "Dallas, TX",
            EstimatedDelivery = new DateTime(2026, 6, 10, 17, 0, 0, DateTimeKind.Utc),
            StatusUpdates =
            [
                new StatusUpdate { Timestamp = new DateTime(2026, 6, 2, 16, 0, 0, DateTimeKind.Utc), Description = "Label created", Location = "Dallas, TX" },
            ]
        },
    };

    public async Task<Shipment?> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        await Task.Delay(1500, ct);
        SeedData.TryGetValue(trackingNumber, out var shipment);
        return shipment;
    }
}

